#!/usr/bin/env python3
"""Render measured tables; no interpolation for unobserved CPU attribution."""
import json
from pathlib import Path
from statistics import mean

ROOT = Path(__file__).resolve().parent
d = json.loads((ROOT / "analysis.json").read_text())
lines = ["# Derived measurement tables", "", "Generated by `report_tables.py`; nested CPU spans are not additive. All throughput tables use uninstrumented builds.", ""]

def table(headers, rows):
    lines.append("| " + " | ".join(headers) + " |")
    lines.append("| " + " | ".join("---" for _ in headers) + " |")
    lines.extend("| " + " | ".join(map(str, row)) + " |" for row in rows)
    lines.append("")

def f(value):
    return f"{value:.3f}"

for os in ("linux", "macos"):
    directory = f"ci-{os}-postfix" if (ROOT / f"ci-{os}-postfix/uninstrumented.json").exists() else f"ci-{os}-final"
    lines += [f"## {os}: {directory}", "", f"Source: `{(ROOT / directory / 'source-sha.txt').read_text().strip()}`. Binary hashes and exact commands are in each raw JSON.", ""]
    performance = d["performance"][f"{directory}/uninstrumented.json"]
    lines += ["### Keep-alive throughput and latency", "", "T=Threaded; R=Reactor; Pxx is milliseconds. Hosted-runner noise remains possible.", ""]
    table(["Conn", "Endpoint", "T before req/s", "T after req/s", "R before req/s", "R after req/s", "R change %", "R vs T %", "Observed gap closed %", "T P50/P95/P99", "R P50/P95/P99"], [
        [r["connections"], r["endpoint"], *[round(r["labels"][label]["rps"]) for label in ("threaded-before", "threaded", "before", "reactor")], f(r["reactor_improvement_percent"]), f(r["remaining_vs_threaded_percent"]), f(r["observed_gap_closed_percent"]) if r["observed_gap_closed_percent"] is not None else "unknown", *["/".join(f(r["labels"][label]["latency_ms"][p]) for p in ("p50", "p95", "p99")) for label in ("threaded", "reactor")]]
        for r in performance if r["kind"] == "keep_alive"
    ])
    lines += ["### Keep-alive resource cost", "", "CPU/request is derived from coarse process CPU / req/s. Allocation includes startup/connection setup; allocator excludes libc/SQLite internals.", ""]
    raw = json.loads((ROOT / directory / "uninstrumented.json").read_text())
    rows = []
    for r in performance:
        if r["kind"] != "keep_alive":
            continue
        for label in ("threaded", "reactor"):
            v = r["labels"][label]
            runs = [x for x in raw["runs"] if x.get("kind") == r["kind"] and x.get("connections") == r["connections"] and x.get("endpoint") == r["endpoint"] and x.get("label") == label]
            requests = mean(sum(x["oha"]["statusCodeDistribution"].values()) for x in runs)
            rows.append([r["connections"], r["endpoint"], label, f(v["cpu_percent"]), f(v["cpu_percent"] / 100 / v["rps"] * 1e6), round(v["rss_kib"]), v["threads_peak"], f(v["allocation_calls"] / requests), f(v["shutdown_ms"])])
    table(["Conn", "Endpoint", "Runtime", "CPU %", "CPU us/req estimate", "RSS KiB", "Threads peak", "Alloc/req", "Shutdown ms"], rows)
    lines += ["### Short-lived latency at fixed 500 qps", "", "This is not a saturated throughput comparison. CPU snapshots may round to zero.", ""]
    table(["Conn", "Endpoint", "T req/s", "R req/s", "T P50/P95/P99 ms", "R P50/P95/P99 ms"], [
        [r["connections"], r["endpoint"], *[f(r["labels"][label]["rps"]) for label in ("threaded", "reactor")], *["/".join(f(r["labels"][label]["latency_ms"][p]) for p in ("p50", "p95", "p99")) for label in ("threaded", "reactor")]] for r in performance if r["kind"] == "short_lived"
    ])
    lines += ["### c32 inclusive instrumentation", "", "Cells are CPU us / wall us per request. `read` intervals have different waiting scopes; queue/completion wait has no CPU measurement.", ""]
    rows = []
    attribution = d["attribution"][f"{directory}/cost.json"]
    for ep in ("hello", "echo", "db/1"):
        selected = {r["label"]: r["intervals"] for r in attribution if r["connections"] == 32 and r["kind"] == "keep_alive" and r["endpoint"] == ep}
        for interval in ("read", "parse", "enqueue", "worker_lock", "worker_wait", "queue_wait", "dispatch", "serialize", "completion_publish", "completion_wait", "selector_update", "selector_wait", "send"):
            rows.append([ep, interval, *["unknown / " + f(selected[label][interval]["wall_us_per_request"]) if interval in ("queue_wait", "completion_wait") and label == "reactor" else f(selected[label][interval]["cpu_us_per_request"]) + " / " + f(selected[label][interval]["wall_us_per_request"]) for label in ("threaded", "reactor")]])
    table(["Endpoint", "Interval", "Threaded CPU/wall us", "Reactor CPU/wall us"], rows)
    lines += ["### c32 hello invocations per request", ""]
    selected = {r["label"]: r["intervals"] for r in attribution if r["connections"] == 32 and r["kind"] == "keep_alive" and r["endpoint"] == "hello"}
    table(["Operation", "Threaded", "Reactor"], [[k, f(selected["threaded"][k]["count_per_request"]), f(selected["reactor"][k]["count_per_request"])] for k in ("parse", "dispatch", "enqueue", "worker_lock", "condition_signal", "condition_wait", "mutex_lock", "notify", "wake_write", "wake_read", "loop", "selector_add", "selector_modify", "selector_delete", "selector_same", "writable_enable", "writable_disable", "copy_bytes", "send_call", "readvec_call", "recv_call")])
    lines += ["### Session resources", "", "Idle snapshot CPU includes recent establishment, not a steady-idle percentage. See soak samples for drift. All counts are observed, not extrapolated.", ""]
    rows = []
    for label in ("threaded", "reactor"):
        key = f"{directory}/sessions-{label}.json"
        for r in d["memory"].get(key, []):
            s = r["resources"]
            rows.append([r["adapter"], r["count"], round(s["allocator"]["live"] / 1024**2, 2), round(s["rss_kib"] / 1024, 2), s["threads"], s["fds"], f(r["establishment_ms"]), f(r["broadcast_ms"]), f(r["shutdown_ms"]), r["clean"]])
    table(["Adapter", "Idle", "Live MiB", "RSS MiB", "Threads", "FDs", "Establish ms", "Broadcast ms", "Shutdown ms", "Clean"], rows)
    for label in ("threaded", "reactor"):
        data = json.loads((ROOT / directory / f"sessions-{label}.json").read_text())
        mixed = next(r for r in data["runs"] if r["scenario"] == "mixed-soak-races")
        lines += [f"{label} mixed soak: requested {mixed['requested_soak_s']} s, observed {mixed['elapsed_s']:.1f} s, {mixed['iterations']} iterations, HTTP isolated `{mixed['http_isolated']}`, cleanup `{mixed['clean']}`. Full drift samples/endpoint latency are in raw JSON.", ""]

lines += ["## Linux traced syscall count/request", "", "10,000 requests; strace perturbs synchronization. Startup/shutdown included; context switches unknown.", ""]
directory = "ci-linux-postfix" if (ROOT / "ci-linux-postfix").exists() else "ci-linux-final"
table(["Endpoint", "Runtime", "recv", "send", "poll/epoll_wait", "epoll_ctl", "wake write", "pipe read", "accept", "futex", "total"], [[ep, label, *[f(v["counts"].get(k, {}).get("calls_per_request", 0)) for k in (("recvmsg" if label == "threaded" else "recvfrom"), "sendto", ("poll" if label == "threaded" else "epoll_wait"), "epoll_ctl", "write", "read", "accept", "futex", "total")]] for ep in ("hello", "echo", "db-1") for label in ("threaded", "before", "reactor") for v in [d["syscalls"][f"{directory}/syscalls-{label}-{ep}/syscalls.txt"]]])
(ROOT / "report-tables.md").write_text("\n".join(lines) + "\n")
print("Wrote report-tables.md from measured raw data")
